-- D89. Ship to site: each website's publish secret is generated by the administrator, set in
-- the website's own deployment (GENIE_WORKS_PUBLISH_SECRET) and pasted into Genie Works, which
-- keeps it only encrypted (AES-256-GCM, ANALYTICS_TOKEN_KEY). The plaintext is never stored or
-- shown again. 0057's derived-secret `generation` column stays, unused.

alter table website_blog_publishing
  add column secret_ciphertext text,
  add column secret_nonce text,
  add column secret_key_version integer,
  add column secret_set_at timestamptz,
  add constraint website_blog_publishing_secret_shape check (
    (secret_ciphertext is null and secret_nonce is null and secret_key_version is null and secret_set_at is null)
    or (secret_ciphertext is not null and secret_nonce is not null and secret_key_version is not null and secret_set_at is not null)
  );
